const INTAKE_ACCOUNTING_TEXT_CAPACITY_CONTRACT=Object.freeze({version:'closed-loop-intake-accounting-text-capacity/1',stage:1,field:'INPUT_SET_CONTENTS',operations:Object.freeze(['COMPLETE','RECONCILE_INTAKE']),rule:'The complete INPUT_SET_CONTENTS accounting string may use up to the effective raw response byte allowance in UTF-16 code units. The entire serialized UTF-8 response must still fit its separately published byte allowance. Other text fields retain their ordinary text limit; complete intake, provenance and independent challenge obligations remain unchanged.'});
